class VerificationError(RuntimeError):
    """A generated run is incomplete, damaged, or inconsistent."""


def _read_object(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise VerificationError(f"could not read JSON object {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise VerificationError(f"expected a JSON object: {path}")
    return value


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    try:
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError as exc:
        raise VerificationError(f"could not hash generated prerequisite {path}: {exc}") from exc
    return digest.hexdigest()


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    try:
        with path.open("r", encoding="utf-8") as stream:
            for line_number, line in enumerate(stream, start=1):
                if not line.strip():
                    continue
                value = json.loads(line)
                if not isinstance(value, dict):
                    raise VerificationError(f"non-object JSONL row at {path}:{line_number}")
                records.append(value)
    except (OSError, json.JSONDecodeError) as exc:
        raise VerificationError(f"could not read JSONL {path}: {exc}") from exc
    return records


def _finite_tree(value: Any, *, location: str) -> None:
    if isinstance(value, Mapping):
        for key, item in value.items():
            _finite_tree(item, location=f"{location}.{key}")
    elif isinstance(value, (list, tuple)):
        for index, item in enumerate(value):
            _finite_tree(item, location=f"{location}[{index}]")
    elif isinstance(value, float) and not math.isfinite(value):
        raise VerificationError(f"non-finite numeric value at {location}")


def _nonnegative_integer(value: Any, *, location: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise VerificationError(f"expected a non-negative integer at {location}")
    return value


def _inside(raw: Any, root: Path, *, field: str) -> Path:
    if not isinstance(raw, str) or not raw:
        raise VerificationError(f"{field} must be a non-empty path string")
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = root / path
    resolved = path.resolve()
    if not resolved.is_relative_to(root):
        raise VerificationError(f"{field} escapes its generated workspace")
    return resolved


def _verify_histogram(
    record: Mapping[str, Any],
    *,
    histogram_name: str,
    total_name: str,
    location: str,
) -> dict[str, int]:
    raw = record.get(histogram_name)
    if not isinstance(raw, Mapping):
        raise VerificationError(f"{histogram_name} is not an object at {location}")
    histogram: dict[str, int] = {}
    for key, count in raw.items():
        name = str(key)
        if name.startswith("_"):
            raise VerificationError(f"transport-only histogram key at {location}")
        histogram[name] = _nonnegative_integer(
            count, location=f"{location}.{histogram_name}.{name}"
        )
    total = _nonnegative_integer(record.get(total_name), location=f"{location}.{total_name}")
    if sum(histogram.values()) != total:
        raise VerificationError(f"{histogram_name} does not sum to {total_name} at {location}")
    return histogram


def _verify_episode_records(
    records: Sequence[Mapping[str, Any]],
    *,
    variant: str,
    final_step: int,
    batch_size: int,
    num_envs: int,
    updates: int,
    completed_episodes: int,
    max_episode_steps: int,
    location: str,
) -> dict[str, Any]:
    if not records:
        raise VerificationError(f"episode telemetry is empty: {location}")
    if len(records) != completed_episodes:
        raise VerificationError("episode telemetry count differs from the run manifest")
    completion_order: list[tuple[int, int]] = []
    for index, record in enumerate(records, start=1):
        row = f"{location}:{index}"
        if record.get("schema_version") != TELEMETRY_SCHEMA_VERSION:
            raise VerificationError(f"episode telemetry schema mismatch at {row}")
        if record.get("variant_id") != variant:
            raise VerificationError(f"episode telemetry variant mismatch at {row}")
        episode_id = _nonnegative_integer(record.get("episode_id"), location=f"{row}.episode_id")
        if episode_id != index or record.get("completed_episode_count") != episode_id:
            raise VerificationError(f"episode IDs are not consecutive at {row}")
        update = _nonnegative_integer(record.get("update"), location=f"{row}.update")
        if not 1 <= update <= updates:
            raise VerificationError(f"episode update is outside the run at {row}")
        if record.get("global_step") != update * batch_size:
            raise VerificationError(f"episode rollout step does not match its update at {row}")
        completion_step = _nonnegative_integer(
            record.get("completion_global_step", record.get("global_step")),
            location=f"{row}.completion_global_step",
        )
        lower = (update - 1) * batch_size
        if (
            not lower < completion_step <= update * batch_size
            or completion_step > final_step
            or completion_step % num_envs
        ):
            raise VerificationError(f"episode completion step is inconsistent at {row}")
        episode_length = _nonnegative_integer(
            record.get("episode_length"), location=f"{row}.episode_length"
        )
        if not 1 <= episode_length <= max_episode_steps:
            raise VerificationError(f"episode length is outside the environment horizon at {row}")
        actions = _verify_histogram(
            record,
            histogram_name="action_histogram",
            total_name="episode_length",
            location=row,
        )
        action_limit = 11 if get_variant_spec(variant).diagnosis_actions else 9
        if not set(actions).issubset(DEFAULT_ACTION_NAMES[:action_limit]):
            raise VerificationError(f"episode telemetry has an unavailable action at {row}")
        _verify_histogram(
            record,
            histogram_name="magnification_histogram",
            total_name="observed_views",
            location=row,
        )
        _finite_tree(record, location=row)
        completion_order.append((completion_step, episode_id))
    if completion_order != sorted(completion_order):
        raise VerificationError(f"episode telemetry is out of completion order: {location}")
    return aggregate_episode_records(records)


def _verify_rollout_records(
    records: Sequence[Mapping[str, Any]],
    *,
    variant: str,
    final_step: int,
    batch_size: int,
    updates: int,
    episodes: Sequence[Mapping[str, Any]],
    location: str,
) -> None:
    if len(records) != updates:
        raise VerificationError(
            f"rollout telemetry has {len(records)} rows, expected {updates}: {location}"
        )
    completed_total = 0
    for index, record in enumerate(records, start=1):
        row = f"{location}:{index}"
        if record.get("schema_version") != TELEMETRY_SCHEMA_VERSION:
            raise VerificationError(f"rollout telemetry schema mismatch at {row}")
        if record.get("variant_id") != variant:
            raise VerificationError(f"rollout telemetry variant mismatch at {row}")
        step = _nonnegative_integer(record.get("global_step"), location=f"{row}.global_step")
        if step != index * batch_size or step > final_step:
            raise VerificationError(f"rollout steps do not follow the exact batch grid at {row}")
        if record.get("update") != index:
            raise VerificationError(f"rollout update number is not consecutive at {row}")
        if record.get("transitions") != batch_size:
            raise VerificationError(f"rollout transition count does not equal batch size at {row}")
        actions = _verify_histogram(
            record,
            histogram_name="action_counts",
            total_name="transitions",
            location=row,
        )
        action_limit = 11 if get_variant_spec(variant).diagnosis_actions else 9
        if not set(actions).issubset(DEFAULT_ACTION_NAMES[:action_limit]):
            raise VerificationError(f"rollout telemetry has an unavailable action at {row}")
        completed = _nonnegative_integer(
            record.get("completed_episodes"), location=f"{row}.completed_episodes"
        )
        observed_completed = sum(int(episode.get("update", -1)) == index for episode in episodes)
        if completed != observed_completed:
            raise VerificationError(f"rollout completed-episode count mismatch at {row}")
        completed_total += completed
        cumulative = record.get("cumulative")
        if not isinstance(cumulative, Mapping) or cumulative.get("episodes") != completed_total:
            raise VerificationError(f"rollout cumulative episode count mismatch at {row}")
        counts = record.get("action_counts")
        expected_fractions = {str(name): int(count) / batch_size for name, count in counts.items()}
        if record.get("action_fractions") != expected_fractions:
            raise VerificationError(f"rollout action fractions mismatch at {row}")
        _finite_tree(record, location=row)
    if records[-1].get("global_step") != final_step:
        raise VerificationError(f"rollout telemetry does not reach the final step: {location}")
    if completed_total != len(episodes):
        raise VerificationError("rollout and episode telemetry totals disagree")


def _verify_checkpoint(
    checkpoint_dir: Path,
    *,
    final_step: int,
    updates: int,
    completed_episodes: int,
    ppo_config: Mapping[str, Any],
    dependencies: Mapping[str, Any],
) -> Path:
    from wsi_lab.rl.checkpoints import inspect_ppo_checkpoint

    candidates: list[tuple[int, Path]] = []
    if checkpoint_dir.is_dir():
        for path in checkpoint_dir.glob("checkpoint_*.pt"):
            match = re.fullmatch(r"checkpoint_(\d{12})\.pt", path.name)
            if match and path.is_file():
                candidates.append((int(match.group(1)), path))
    if not candidates:
        raise VerificationError(f"checkpoint directory is empty: {checkpoint_dir}")
    filename_step, latest_path = max(candidates)
    if filename_step != final_step:
        raise VerificationError("latest checkpoint filename does not match the final step")
    try:
        latest = inspect_ppo_checkpoint(latest_path)
    except (OSError, ValueError) as exc:
        raise VerificationError(f"could not inspect final checkpoint: {exc}") from exc
    if latest.global_step != final_step:
        raise VerificationError("final checkpoint payload has the wrong global step")
    if latest.update != updates:
        raise VerificationError("final checkpoint update count does not match the run manifest")
    if dict(latest.config) != dict(ppo_config):
        raise VerificationError("final checkpoint PPO configuration does not match the run")
    if dict(latest.dependencies) != dict(dependencies):
        raise VerificationError("final checkpoint dependencies do not match the run manifest")
    if latest.extra.get("final") is not True:
        raise VerificationError("final checkpoint is not marked final")
    if latest.extra.get("completed_episode_count") != completed_episodes:
        raise VerificationError("final checkpoint completed-episode count does not match the run")
    return latest_path


def _verify_telemetry(
    artifact_dir: Path,
    *,
    variant: str,
    final_step: int,
    batch_size: int,
    num_envs: int,
    updates: int,
    completed_episodes: int,
    max_episode_steps: int,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    telemetry_dir = artifact_dir / "telemetry"
    episodes_path = telemetry_dir / "training_episodes.jsonl"
    rollouts_path = telemetry_dir / "training_rollouts.jsonl"
    state_path = telemetry_dir / "telemetry_state.json"
    episodes = _read_jsonl(episodes_path)
    rollouts = _read_jsonl(rollouts_path)
    aggregate = _verify_episode_records(
        episodes,
        variant=variant,
        final_step=final_step,
        batch_size=batch_size,
        num_envs=num_envs,
        updates=updates,
        completed_episodes=completed_episodes,
        max_episode_steps=max_episode_steps,
        location=str(episodes_path),
    )
    _verify_rollout_records(
        rollouts,
        variant=variant,
        final_step=final_step,
        batch_size=batch_size,
        updates=updates,
        episodes=episodes,
        location=str(rollouts_path),
    )
    state = _read_object(state_path)
    expected_state = {
        "schema_version": TELEMETRY_SCHEMA_VERSION,
        "status": "complete",
        "variant_id": variant,
        "global_step": final_step,
        "episodes": completed_episodes,
        "last_episode_id": completed_episodes,
        "episode_jsonl": str(episodes_path.resolve()),
        "rollout_jsonl": str(rollouts_path.resolve()),
        "cumulative": aggregate,
    }
    mismatches = {
        name: (state.get(name), value)
        for name, value in expected_state.items()
        if state.get(name) != value
    }
    if mismatches:
        raise VerificationError(f"telemetry completion mismatch: {sorted(mismatches)}")
    _finite_tree(state, location=str(state_path))
    expected_window = aggregate_episode_records(episodes[-256:])
    if state.get("window") != expected_window:
        raise VerificationError("telemetry trailing-window aggregate mismatch")
    return episodes, aggregate


def _verify_training_progress(
    artifact_dir: Path,
    *,
    run_fingerprint: str,
    variant: str,
    final_step: int,
    updates: int,
    last_metrics: Mapping[str, Any],
) -> Path:
    path = artifact_dir / "training_progress.json"
    progress = _read_object(path)
    expected = {
        "schema_version": TRAINING_PROGRESS_SCHEMA_VERSION,
        "status": "update_complete",
        "run_fingerprint": run_fingerprint,
        "variant": variant,
        "global_step": final_step,
        "updates": updates,
        "last_metrics": dict(last_metrics),
    }
    mismatches = [name for name, value in expected.items() if progress.get(name) != value]
    if mismatches:
        raise VerificationError(f"durable training progress mismatch: {sorted(mismatches)}")
    _finite_tree(progress, location=str(path))
    return path


def _read_trajectory(path: Path) -> dict[str, Any]:
    try:
        with gzip.open(path, "rt", encoding="utf-8") as stream:
            value = json.load(stream)
    except (OSError, json.JSONDecodeError) as exc:
        raise VerificationError(f"could not read monitoring trajectory {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise VerificationError(f"monitoring trajectory is not an object: {path}")
    return value


def _verify_monitoring(
    artifact_dir: Path,
    workspace: Path,
    *,
    mode: str,
    variant: str,
    start: str,
    final_step: int,
) -> dict[str, int]:
    study = load_study()
    milestones = (
        [int(value) for value in study["monitoring"]["milestones"]]
        if mode == "main"
        else [int(study["smoke"]["requested_timesteps"])]
    )
    expected_slides = int(study["monitoring"]["cohort_size"]) if mode == "main" else 2
    cache_root = workspace.parent / "analysis_cache"
    cache_manifest = _read_object(cache_root / "manifest.json")
    if (
        cache_manifest.get("status") != "complete"
        or cache_manifest.get("scope") != "training-only-analysis"
        or cache_manifest.get("train_only") is not True
    ):
        raise VerificationError("analysis cache is not a complete training-only cache")
    entries = cache_manifest.get("entries")
    if not isinstance(entries, Mapping) or not entries:
        raise VerificationError("analysis cache has no indexed training entries")
    cohort_document = _read_object(cache_root / "monitor_slides.json")
    expected_selection = {
        "split": "train",
        "cohort_size": int(study["monitoring"]["cohort_size"]),
        "positive_slides": int(study["monitoring"]["positive_slides"]),
        "seed": int(study["monitoring"]["cohort_seed"]),
        "positive_annotation_requirement": "available_and_exhaustive",
    }
    if (
        cohort_document.get("schema_version") != 1
        or cohort_document.get("selection") != expected_selection
    ):
        raise VerificationError("analysis monitoring cohort selection contract is invalid")
    full_cohort = cohort_document.get("slides")
    if not isinstance(full_cohort, list) or len(full_cohort) != int(
        study["monitoring"]["cohort_size"]
    ):
        raise VerificationError("analysis cache has an invalid monitoring cohort")
    if any(not isinstance(item, Mapping) for item in full_cohort):
        raise VerificationError("analysis monitoring cohort contains a non-object entry")
    if len({str(item.get("slide_id", "")) for item in full_cohort}) != len(full_cohort):
        raise VerificationError("analysis monitoring cohort has missing or duplicate slide IDs")
    if any(str(item.get("split", "train")) != "train" for item in full_cohort):
        raise VerificationError("analysis monitoring cohort is not training-only")
    expected_cohort = select_monitor_cohort(
        (
            {
                "slide_id": str(slide_id),
                "label": int(entry.get("label", -1)),
                "split": "train",
                "annotation_available": bool(entry.get("annotation_available")),
                "annotation_exhaustive": bool(entry.get("annotation_exhaustive")),
            }
            for slide_id, entry in entries.items()
            if isinstance(entry, Mapping)
        ),
        cohort_size=int(study["monitoring"]["cohort_size"]),
        positive_slides=int(study["monitoring"]["positive_slides"]),
        seed=int(study["monitoring"]["cohort_seed"]),
    )
    if tuple(str(item.get("slide_id", "")) for item in full_cohort) != tuple(
        str(item["slide_id"]) for item in expected_cohort
    ):
        raise VerificationError("analysis monitoring cohort is not the deterministic selection")
    for item in full_cohort:
        entry = entries.get(str(item["slide_id"]))
        if not isinstance(entry, Mapping) or any(
            item.get(name) != entry.get(name)
            for name in ("label", "annotation_available", "annotation_exhaustive")
        ):
            raise VerificationError("analysis monitoring cohort differs from its cache entry")
    positives = [item for item in full_cohort if int(item.get("label", -1)) == 1]
    negatives = [item for item in full_cohort if int(item.get("label", -1)) == 0]
    if len(positives) != int(study["monitoring"]["positive_slides"]):
        raise VerificationError("analysis monitoring cohort has the wrong positive count")
    if len(positives) + len(negatives) != len(full_cohort):
        raise VerificationError("analysis monitoring cohort contains an invalid label")
    if any(
        item.get("annotation_available") is not True
        or item.get("annotation_exhaustive") is not True
        for item in positives
    ):
        raise VerificationError("positive monitoring slides require exhaustive annotations")
    selected_cohort = full_cohort if mode == "main" else [positives[0], negatives[0]]
    expected_slide_ids = tuple(str(item["slide_id"]) for item in selected_cohort)
    monitoring_dir = artifact_dir / "monitoring"
    manifest_path = monitoring_dir / "manifest.json"
    manifest = _read_object(manifest_path)
    identity = {
        "schema_version": MONITORING_SCHEMA_VERSION,
        "status": "complete",
        "variant_id": variant,
        "expected_milestones": milestones,
        "cohort_sha256": cohort_sha256(selected_cohort),
    }
    mismatches = {
        name: (manifest.get(name), value)
        for name, value in identity.items()
        if manifest.get(name) != value
    }
    if mismatches:
        raise VerificationError(f"monitoring completion mismatch: {sorted(mismatches)}")
    completed = manifest.get("completed")
    if not isinstance(completed, list):
        raise VerificationError("monitoring completion records are missing")
    if [item.get("nominal_step") for item in completed if isinstance(item, Mapping)] != milestones:
        raise VerificationError("monitoring milestones are incomplete or out of order")
    slide_ids_by_milestone: list[tuple[str, ...]] = []
    trajectory_count = 0
    overlay_count = 0
    for item in completed:
        if not isinstance(item, Mapping):
            raise VerificationError("monitoring completion record is not an object")
        nominal = _nonnegative_integer(item.get("nominal_step"), location="monitor.nominal_step")
        actual = _nonnegative_integer(item.get("actual_step"), location="monitor.actual_step")
        if not nominal <= actual <= final_step:
            raise VerificationError("monitoring actual step is outside its run")
        if item.get("slides") != expected_slides:
            raise VerificationError("monitoring cohort has the wrong number of slides")
        expected_output = (monitoring_dir / f"step_{nominal:012d}").resolve()
        output_dir = _inside(item.get("output_dir"), workspace, field="monitor.output_dir")
        if output_dir != expected_output:
            raise VerificationError("monitoring milestone uses an unexpected output directory")
        summary_path = _inside(item.get("summary"), workspace, field="monitor.summary")
        if summary_path != output_dir / "summary.json":
            raise VerificationError("monitoring milestone uses an unexpected summary path")
        summary = _read_object(summary_path)
        summary_identity = {
            "schema_version": MONITORING_SCHEMA_VERSION,
            "variant_id": variant,
            "nominal_step": nominal,
            "actual_step": actual,
        }
        if any(summary.get(name) != value for name, value in summary_identity.items()):
            raise VerificationError("monitoring summary identity mismatch")
        slides = summary.get("slides")
        if not isinstance(slides, list) or len(slides) != expected_slides:
            raise VerificationError("monitoring summary has the wrong slide count")
        slide_ids: list[str] = []
        for slide in slides:
            if not isinstance(slide, Mapping):
                raise VerificationError("monitoring slide summary is not an object")
            slide_id = str(slide.get("slide_id", ""))
            if not slide_id or slide_id in slide_ids:
                raise VerificationError("monitoring slide IDs are missing or duplicated")
            slide_ids.append(slide_id)
            trajectory_path = _inside(
                slide.get("trajectory"), workspace, field="monitor.trajectory"
            )
            overlay_path = _inside(slide.get("overlay"), workspace, field="monitor.overlay")
            expected_slide_root = output_dir / slide_id
            if trajectory_path != expected_slide_root / "trajectory.json.gz":
                raise VerificationError("monitoring trajectory path is unexpected")
            if overlay_path != expected_slide_root / "overlay.png":
                raise VerificationError("monitoring overlay path is unexpected")
            trajectory = _read_trajectory(trajectory_path)
            trajectory_identity = {
                "schema_version": MONITORING_SCHEMA_VERSION,
                "variant_id": variant,
                "start_strategy": start,
                "nominal_step": nominal,
                "actual_step": actual,
                "slide_id": slide_id,
                "label": int(selected_cohort[len(slide_ids) - 1]["label"]),
                "reset_seed": monitor_reset_seed(int(study["monitoring"]["cohort_seed"]), slide_id),
            }
            if any(trajectory.get(name) != value for name, value in trajectory_identity.items()):
                raise VerificationError("monitoring trajectory identity mismatch")
            points = trajectory.get("trajectory")
            episode_summary = trajectory.get("episode_summary")
            cohort_record = trajectory.get("cohort_record")
            if not isinstance(points, list) or not points:
                raise VerificationError("monitoring trajectory records are missing")
            if not isinstance(episode_summary, Mapping):
                raise VerificationError("monitoring trajectory has no episode summary")
            if not isinstance(cohort_record, Mapping) or any(
                cohort_record.get(name) != selected_cohort[len(slide_ids) - 1].get(name)
                for name in (
                    "slide_id",
                    "label",
                    "annotation_available",
                    "annotation_exhaustive",
                )
            ):
                raise VerificationError("monitoring trajectory has the wrong cohort record")
            episode_length = _nonnegative_integer(
                episode_summary.get("episode_length"),
                location=f"{trajectory_path}.episode_summary.episode_length",
            )
            if episode_length <= 0 or len(points) != episode_length + 1:
                raise VerificationError("monitoring trajectory length is inconsistent")
            for point_index, point in enumerate(points):
                if not isinstance(point, Mapping) or point.get("step") != point_index:
                    raise VerificationError("monitoring trajectory steps are malformed")
                bounds = point.get("canonical_bounds")
                if (
                    not isinstance(bounds, list)
                    or len(bounds) != 4
                    or any(
                        isinstance(value, bool) or not isinstance(value, int) for value in bounds
                    )
                    or bounds[2] <= bounds[0]
                    or bounds[3] <= bounds[1]
                ):
                    raise VerificationError("monitoring trajectory bounds are malformed")
                terminal = bool(point.get("terminated")) or bool(point.get("truncated"))
                if terminal != (point_index == episode_length):
                    raise VerificationError("monitoring trajectory terminal flags are malformed")
            if points[0].get("action") is not None:
                raise VerificationError("monitoring trajectory does not begin at reset")
            if any(
                slide.get(name) != episode_summary.get(name)
                for name in ("slide_id", "label", "episode_length", "terminated", "truncated")
            ):
                raise VerificationError("monitoring slide and trajectory summaries differ")
            _finite_tree(trajectory, location=str(trajectory_path))
            try:
                from PIL import Image

                with Image.open(overlay_path) as overlay:
                    if overlay.format != "PNG" or overlay.width <= 0 or overlay.height <= 0:
                        raise VerificationError("monitoring overlay has invalid PNG metadata")
                    overlay.verify()
            except VerificationError:
                raise
            except (OSError, SyntaxError, ValueError) as exc:
                raise VerificationError(f"could not read monitoring overlay: {exc}") from exc
            trajectory_count += 1
            overlay_count += 1
        slide_ids_by_milestone.append(tuple(slide_ids))
        if tuple(slide_ids) != expected_slide_ids:
            raise VerificationError("monitoring summary uses the wrong fixed cohort")
        if summary.get("aggregate") != aggregate_episode_records(slides):
            raise VerificationError("monitoring summary aggregate does not match its slides")
        _finite_tree(summary, location=str(summary_path))
    if len(set(slide_ids_by_milestone)) != 1:
        raise VerificationError("monitoring cohort changed between milestones")
    return {"trajectories": trajectory_count, "overlays": overlay_count}


def verify_completed_run(
    expected: Mapping[str, Any],
    *,
    manifest_path: str | Path | None = None,
) -> dict[str, Any]:
    """Verify identity, checkpoint, telemetry, and monitoring for one run."""

    if manifest_path is None:
        manifest_path = expected.get("result_path")
    if not isinstance(manifest_path, (str, Path)):
        raise VerificationError("the expected run has no manifest path")
    path = Path(manifest_path).expanduser().resolve()
    manifest = _read_object(path)
    variant = str(expected["variant"])
    spec = get_variant_spec(variant)
    final_step = _nonnegative_integer(
        expected.get("expected_final_step", manifest.get("expected_final_step")),
        location="expected_final_step",
    )
    identity = {
        "status": "complete",
        "source_revision": SOURCE_REVISION,
        "run_id": str(expected["run_id"]),
        "mode": str(expected["mode"]),
        "variant": variant,
        "start": str(expected["start"]),
        "seed": int(expected["seed"]),
        "split": "train",
        "validation_enabled": False,
        "test_access": False,
        "global_step": final_step,
        "expected_final_step": final_step,
    }
    for name in (
        "schema_version",
        "run_fingerprint",
        "workspace",
        "artifact_dir",
        "checkpoint_dir",
        "result_path",
        "requested_timesteps",
    ):
        if name in expected:
            identity[name] = expected[name]
    mismatches = {
        name: (manifest.get(name), value)
        for name, value in identity.items()
        if manifest.get(name) != value
    }
    if mismatches:
        raise VerificationError(
            f"run manifest identity mismatch for {identity['run_id']}: {sorted(mismatches)}"
        )
    fingerprint = manifest.get("run_fingerprint")
    if not isinstance(fingerprint, str) or re.fullmatch(r"[0-9a-f]{64}", fingerprint) is None:
        raise VerificationError("run fingerprint is missing or malformed")
    workspace_raw = manifest.get("workspace")
    if not isinstance(workspace_raw, str):
        raise VerificationError("run workspace path is missing")
    workspace = Path(workspace_raw).expanduser().resolve()
    artifact_dir = _inside(manifest.get("artifact_dir"), workspace, field="artifact_dir")
    if path.parent != artifact_dir:
        raise VerificationError("run manifest is outside its declared artifact directory")
    checkpoint_dir = _inside(manifest.get("checkpoint_dir"), workspace, field="checkpoint_dir")
    if checkpoint_dir != artifact_dir / "checkpoints":
        raise VerificationError("run checkpoint directory is unexpected")
    result_path = _inside(manifest.get("result_path"), workspace, field="result_path")
    if result_path != path:
        raise VerificationError("run result path does not identify its manifest")
    dependencies = manifest.get("dependencies")
    if not isinstance(dependencies, Mapping):
        raise VerificationError("run manifest has no checkpoint dependencies")
    for name, value in variant_dependencies(spec).items():
        if dependencies.get(name) != value:
            raise VerificationError(f"variant dependency mismatch: {name}")
    if dependencies.get("ablation_run_fingerprint") != fingerprint:
        raise VerificationError("run fingerprint dependency mismatch")
    if dependencies.get("ablation_source_revision") != SOURCE_REVISION:
        raise VerificationError("source revision dependency mismatch")
    if variant in {"v5_no_belief", "v6_combined"} and "belief_fingerprint" in dependencies:
        raise VerificationError("belief-free run contains a belief checkpoint dependency")
    cache_root = workspace.parent / "analysis_cache"
    prerequisite_hashes = {
        "analysis_cache_manifest_sha256": _sha256_file(cache_root / "manifest.json"),
        "analysis_monitor_cohort_sha256": _sha256_file(cache_root / "monitor_slides.json"),
    }
    for name, value in prerequisite_hashes.items():
        if dependencies.get(name) != value:
            raise VerificationError(f"generated analysis prerequisite mismatch: {name}")
    last_metrics = manifest.get("last_metrics")
    if not isinstance(last_metrics, Mapping) or not last_metrics:
        raise VerificationError("run manifest has no final training metrics")
    _finite_tree(last_metrics, location="run_manifest.last_metrics")
    updates = _nonnegative_integer(manifest.get("updates"), location="run_manifest.updates")
    completed_episodes = _nonnegative_integer(
        manifest.get("completed_episodes"), location="run_manifest.completed_episodes"
    )
    duration = manifest.get("duration_seconds")
    if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
        raise VerificationError("run manifest has an invalid duration")
    _finite_tree(duration, location="run_manifest.duration_seconds")
    resolved_config = artifact_dir / "resolved_config.yaml"
    if not resolved_config.is_file() or resolved_config.stat().st_size == 0:
        raise VerificationError("resolved run configuration is missing")
    try:
        from wsi_lab.config.loader import load_config
        from wsi_lab.rl.recurrent_ppo import PPOConfig
        from wsi_lab.utils.fingerprints import fingerprint as calculate_fingerprint

        persisted_config = load_config(resolved_config)
        assert_protocol_config(
            persisted_config,
            variant=variant,
            run_id=str(expected["run_id"]),
            mode=str(expected["mode"]),
        )
        ppo_config = PPOConfig.from_object(persisted_config.rl).to_dict()
        persisted_fingerprint = calculate_fingerprint(
            run_contract_payload(
                persisted_config,
                spec,
                run_id=str(expected["run_id"]),
                mode=str(expected["mode"]),
            )
        )
    except (OSError, TypeError, ValueError, yaml.YAMLError) as exc:
        raise VerificationError(f"could not validate resolved run configuration: {exc}") from exc
    if persisted_fingerprint != fingerprint:
        raise VerificationError("resolved run configuration does not match its fingerprint")
    batch_size = int(ppo_config["num_envs"]) * int(ppo_config["rollout_steps"])
    expected_updates = math.ceil(int(ppo_config["total_timesteps"]) / batch_size)
    if updates != expected_updates:
        raise VerificationError("run update count does not match the resolved PPO configuration")
    if final_step != expected_updates * batch_size:
        raise VerificationError("final step does not match the resolved PPO batch geometry")
    if manifest.get("requested_timesteps") != int(ppo_config["total_timesteps"]):
        raise VerificationError("requested timesteps do not match the resolved PPO configuration")
    if manifest.get("schema_version") != RUNNER_SCHEMA_VERSION:
        raise VerificationError("run manifest schema is incompatible")
    variant_contract = _read_object(artifact_dir / "variant_contract.json")
    if variant_contract != asdict(spec):
        raise VerificationError("persisted variant contract does not match the run")
    progress = _verify_training_progress(
        artifact_dir,
        run_fingerprint=fingerprint,
        variant=variant,
        final_step=final_step,
        updates=updates,
        last_metrics=last_metrics,
    )
    checkpoint = _verify_checkpoint(
        checkpoint_dir,
        final_step=final_step,
        updates=updates,
        completed_episodes=completed_episodes,
        ppo_config=ppo_config,
        dependencies=dependencies,
    )
    episodes, aggregate = _verify_telemetry(
        artifact_dir,
        variant=variant,
        final_step=final_step,
        batch_size=batch_size,
        num_envs=int(ppo_config["num_envs"]),
        updates=updates,
        completed_episodes=completed_episodes,
        max_episode_steps=int(persisted_config.environment.max_episode_steps),
    )
    monitoring = _verify_monitoring(
        artifact_dir,
        workspace,
        mode=str(expected["mode"]),
        variant=variant,
        start=str(expected["start"]),
        final_step=final_step,
    )
    return {
        "manifest": manifest,
        "training_progress": progress,
        "checkpoint": checkpoint,
        "episodes": episodes,
        "telemetry": aggregate,
        "monitoring": monitoring,
    }


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True, type=Path)
    parser.add_argument("--variant", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--mode", required=True, choices=("main", "smoke"))
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    arguments = _parser().parse_args(argv)
    from .runner import describe_run

    try:
        expected = describe_run(
            arguments.config,
            variant=arguments.variant,
            run_id=arguments.run_id,
            mode=arguments.mode,
        )
        report = verify_completed_run(expected)
    except (KeyError, TypeError, ValueError, VerificationError) as exc:
        print(f"verification failed: {exc}")
        return 2
    print(f"verified {report['manifest']['run_id']} at step {report['manifest']['global_step']}")
    return 0


__all__ = ["VerificationError", "main", "verify_completed_run"]


if __name__ == "__main__":
    raise SystemExit(main())
